window.RP_SESSION={"id":"S-15609c16332a","messages":[{"id":"RP-II-0117873","time":"2026-07-17T14:23:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"때는 나름 한적한 오후. 점심을 먹고 약간은 노곤해질 시간. 스텔라의 사무실. 당신은 스텔라의 부름에 스텔라의 사무실로 불려왔습니다.","characters":["P-e6655a038328"]},{"id":"RP-II-0117874","time":"2026-07-17T14:23:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"@리키","characters":["P-e6655a038328"]},{"id":"RP-II-0117875","time":"2026-07-17T14:24:00+09:00","room":"RP II","name":"리키","profile":"리키","identity":"reviewed","type":"dialogue","body":"\"어...무슨 일이시죠?\"","characters":["P-bb4b9d047737"]},{"id":"RP-II-0117876","time":"2026-07-17T14:24:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"앞에 앉으세요. 별 일은 아니고 원래 새로 들어오신 분이 있으면 한번씩 이렇게 면담을 진행하거든요.\"","characters":["P-e6655a038328"]},{"id":"RP-II-0117877","time":"2026-07-17T14:25:00+09:00","room":"RP II","name":"리키","profile":"리키","identity":"reviewed","type":"dialogue","body":"\"아,그렇군요\"\n자리에 앉기","characters":["P-bb4b9d047737"]},{"id":"RP-II-0117878","time":"2026-07-17T14:25:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"요즘 어때요? 잘 지내요?\"","characters":["P-e6655a038328"]},{"id":"RP-II-0117879","time":"2026-07-17T14:26:00+09:00","room":"RP II","name":"리키","profile":"리키","identity":"reviewed","type":"dialogue","body":"\"네. 길드분들도 잘 챙겨주시고. 잘 지내고 있습니다.\"","characters":["P-bb4b9d047737"]},{"id":"RP-II-0117880","time":"2026-07-17T14:27:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"뭐, 대부분은 좋은 사람이니까요.\"\n\n스텔라는 그렇게 말하면서 찻주전자 화로에 불을 붙입니다.","characters":["P-e6655a038328"]},{"id":"RP-II-0117881","time":"2026-07-17T14:27:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"다들 잘 해준다면 누가 잘 해주시나요? 친하게 지내는 길드원은 있어요?\"","characters":["P-e6655a038328"]},{"id":"RP-II-0117882","time":"2026-07-17T14:29:00+09:00","room":"RP II","name":"리키","profile":"리키","identity":"reviewed","type":"dialogue","body":"\"어...대부분 다 잘해주셔요. 친하게 지내는 분은..요즘 아마이 조씨랑 자주 만나긴 했네요.\"","characters":["P-bb4b9d047737"]},{"id":"RP-II-0117883","time":"2026-07-17T14:29:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"아마이씨는 확실히 거의 대부분의 사람들과 잘 지내시니까요. 좋은 분이라고 저도 생각해요.\"","characters":["P-e6655a038328"]},{"id":"RP-II-0117884","time":"2026-07-17T14:30:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"반대로 무섭거나 괴롭히는 그런 사람은 없죠?\"","characters":["P-e6655a038328"]},{"id":"RP-II-0117885","time":"2026-07-17T14:30:00+09:00","room":"RP II","name":"리키","profile":"리키","identity":"reviewed","type":"dialogue","body":"\"음...딱히요?\"","characters":["P-bb4b9d047737"]},{"id":"RP-II-0117886","time":"2026-07-17T14:31:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"네, 알겠습니다.\"","characters":["P-e6655a038328"]},{"id":"RP-II-0117887","time":"2026-07-17T14:31:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"다소 형식적인 질문이 계속될거에요.\"","characters":["P-e6655a038328"]},{"id":"RP-II-0117888","time":"2026-07-17T14:31:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"절차적으로 필요한 부분이니까 잠시 시간 좀 내주세요.\"","characters":["P-e6655a038328"]},{"id":"RP-II-0117889","time":"2026-07-17T14:31:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"어디보자....\"","characters":["P-e6655a038328"]},{"id":"RP-II-0117890","time":"2026-07-17T14:32:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"스텔라는 약간은 누렇게 변한 양피지를 들고서 항목들을 살펴보고서 다시 이야기를 이어갑니다.","characters":["P-e6655a038328"]},{"id":"RP-II-0117891","time":"2026-07-17T14:32:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"길드에 와서 한 일들이 뭐가 있는지 기억 나시나요?\"","characters":["P-e6655a038328"]},{"id":"RP-II-0117892","time":"2026-07-17T14:33:00+09:00","room":"RP II","name":"리키","profile":"리키","identity":"reviewed","type":"dialogue","body":"\"어...별로요? 수다떨기?\"","characters":["P-bb4b9d047737"]},{"id":"RP-II-0117893","time":"2026-07-17T14:34:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"리키, 당신이 길드에 온지 거의 한달이 되어가고 있죠?\"","characters":["P-e6655a038328"]},{"id":"RP-II-0117894","time":"2026-07-17T14:35:00+09:00","room":"RP II","name":"리키","profile":"리키","identity":"reviewed","type":"dialogue","body":"\"어...네.\"","characters":["P-bb4b9d047737"]},{"id":"RP-II-0117895","time":"2026-07-17T14:36:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"사실... 아니 솔직히 말하자면 요즘 길드원들이 많아져서 하나하나 챙기기는 힘든 상황이라는 것을 먼저 이야기 드리고 말할게요.\"","characters":["P-e6655a038328"]},{"id":"RP-II-0117896","time":"2026-07-17T14:36:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"리키씨도 분명 억울한 부분이 있을테니까 감안해서 들어주세요.\"","characters":["P-e6655a038328"]},{"id":"RP-II-0117897","time":"2026-07-17T14:37:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"길드에서 기본으로 제공되는 숙식이 그저 거저나오는 것은 아니에요.\"","characters":["P-e6655a038328"]},{"id":"RP-II-0117898","time":"2026-07-17T14:37:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"모두 당신의 동료와 선배들이 한 의뢰비의 일부를 운영비로 사용하고 있는거고.\"","characters":["P-e6655a038328"]},{"id":"RP-II-0117899","time":"2026-07-17T14:38:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"뭐라고 해야할까요... 사실 리키씨는 그저 사람들과 어울리는 것만을 위해서 길드에 왔다는 생각이 들어요.\"","characters":["P-e6655a038328"]},{"id":"RP-II-0117900","time":"2026-07-17T14:40:00+09:00","room":"RP II","name":"리키","profile":"리키","identity":"reviewed","type":"dialogue","body":"\"아..\"","characters":["P-bb4b9d047737"]},{"id":"RP-II-0117901","time":"2026-07-17T14:40:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"하실 이야기가 있다면 편하게 해주세요.\"","characters":["P-e6655a038328"]},{"id":"RP-II-0117902","time":"2026-07-17T14:42:00+09:00","room":"RP II","name":"리키","profile":"리키","identity":"reviewed","type":"dialogue","body":"\"음...의뢰를 나가지 않은것도 맞고. 그렇다고 딱히 뭔갈 하지도 않았으니...뭐라 할말이 없네요\"","characters":["P-bb4b9d047737"]},{"id":"RP-II-0117903","time":"2026-07-17T14:43:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"좋아요. 솔직하게 말한 부분에 대해서는 높게 이야기 할게요. 이리저리 핑계를 대는 사람보다는 훨씬 나으니까요.\"","characters":["P-e6655a038328"]},{"id":"RP-II-0117904","time":"2026-07-17T14:43:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"의뢰를 왜 안 나갔는지도 이야기할 수 있어요?\"","characters":["P-e6655a038328"]},{"id":"RP-II-0117905","time":"2026-07-17T15:33:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-e6655a038328"]},{"id":"RP-II-0117906","time":"2026-07-17T15:33:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
